-- Execute inside a transaction after the migration; always ROLLBACK.
create temporary table test_ids as select gen_random_uuid() outsider,gen_random_uuid() member,gen_random_uuid() sid,gen_random_uuid() open_item,gen_random_uuid() future_item,gen_random_uuid() draft_item;
grant select on test_ids to authenticated,anon;
insert into auth.users(id,email) select outsider,'outsider-test@example.invalid' from test_ids union all select member,'partner-test@10von100.invalid' from test_ids;
insert into public.couple_members(user_id) select member from test_ids;
insert into public.content_items(id,title,body,unlock_at,published) select open_item,'TEST OPEN','TEST BODY',now()-interval '1 day',true from test_ids union all select future_item,'TEST SECRET','TEST FUTURE',now()+interval '1 year',true from test_ids union all select draft_item,'TEST DRAFT','TEST DRAFT BODY',now()-interval '1 day',false from test_ids;
insert into public.content_media(content_item_id,media_type,storage_path) select open_item,'image','test/open.jpg' from test_ids union all select future_item,'image','test/future.jpg' from test_ids union all select draft_item,'image','test/draft.jpg' from test_ids;
insert into storage.objects(bucket_id,name) values ('content','test/open.jpg'),('content','test/future.jpg'),('content','test/draft.jpg'),('moments','test/private.jpg'),('teasers','test/teaser.jpg');
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label; end if;end$$;
set local role anon;
select pg_temp.assert(not has_function_privilege('anon','public.partner_pin_check(text,text)','execute'),'anon cannot check PIN');
select pg_temp.assert(not has_function_privilege('authenticated','public.partner_pin_configure(uuid,text,boolean)','execute'),'browser cannot configure PIN');
select pg_temp.assert(not has_table_privilege('anon','public.content_items','TRUNCATE'),'anon cannot truncate application data');
select pg_temp.assert(not has_table_privilege('authenticated','public.admin_users','TRUNCATE'),'authenticated cannot truncate admin registry');
select pg_temp.assert(not exists(select 1 from public.public_surprise_schedule() where id=(select draft_item from test_ids)),'draft hidden from public schedule');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'role','authenticated')::text,true) from test_ids;
set local role authenticated;
select pg_temp.assert((select count(*)=0 from public.content_items where id in(select open_item from test_ids union select future_item from test_ids union select draft_item from test_ids)),'outsider cannot read content');
select pg_temp.assert((select count(*)=0 from public.content_media where storage_path like 'test/%'),'outsider cannot read media rows');
select pg_temp.assert((select count(*)=0 from storage.objects where name like 'test/%'),'outsider cannot read private storage');
select pg_temp.assert((select count(*)=0 from public.public_unlocked_surprises()),'outsider RPC denied');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',member,'role','authenticated')::text,true) from test_ids;
set local role authenticated;
select pg_temp.assert((select count(*)=1 from public.content_items where id in(select open_item from test_ids union select future_item from test_ids union select draft_item from test_ids)),'member only sees published open item');
select pg_temp.assert((select count(*)=1 from storage.objects where bucket_id='content' and name like 'test/%'),'member only sees open media');
select pg_temp.assert((select count(*)=0 from storage.objects where bucket_id in('moments','teasers') and name like 'test/%'),'orphan moments and teasers denied');
insert into public.year_moments(caption,created_by) select 'TEST MEMORY',member from test_ids;
select pg_temp.assert(exists(select 1 from public.year_moments where caption='TEST MEMORY'),'member can create memory');
insert into storage.objects(bucket_id,name) select 'moments',created_by::text||'/'||id::text||'/test.jpg' from public.year_moments where caption='TEST MEMORY';
select pg_temp.assert(exists(select 1 from storage.objects where bucket_id='moments' and name like '%/test.jpg'),'author can read own orphan upload to clean up failed photo insert');
insert into public.moment_photos(moment_id,storage_path) select id,created_by::text||'/'||id::text||'/test.jpg' from public.year_moments where caption='TEST MEMORY';
delete from storage.objects where bucket_id='moments' and name like '%/test.jpg';
delete from public.year_moments where caption='TEST MEMORY';
select pg_temp.assert(not exists(select 1 from public.moment_photos where storage_path like '%/test.jpg'),'author delete cascades photo rows');
reset role;
select public.partner_pin_configure(member,'4826',false) from test_ids;
select pg_temp.assert((select pin_hash<>'4826' and pin_hash like '$2a$12$%' from private.partner_access),'bcrypt cost 12');
select pg_temp.assert(public.partner_pin_check('4826',repeat('a',64)) is not null,'correct PIN');
select public.partner_pin_check('4826',repeat('e',64)) from generate_series(1,10);
select pg_temp.assert(public.partner_pin_check('4826',repeat('e',64)) is null,'IP limit also applies to correct PIN');
select public.partner_pin_check('1111',repeat('b',64)) from generate_series(1,5);
select pg_temp.assert(public.partner_pin_check('4826',repeat('c',64)) is null,'global cooldown applies across IPs');
update private.partner_access set blocked_until=now()-interval '1 second';
select pg_temp.assert(public.partner_pin_check('4826',repeat('c',64)) is not null,'cooldown expiry');
update private.partner_access set failures=20,blocked_until=null;
select pg_temp.assert(public.partner_pin_check('4826',repeat('d',64)) is null,'hard lock cannot be bypassed by correct PIN');
select public.partner_pin_configure(member,'4826',false) from test_ids;
insert into auth.sessions(id,user_id) select sid,member from test_ids;
select pg_temp.assert(public.partner_pin_register(member,(select revision from private.partner_access),sid),'register live session') from test_ids;
select set_config('request.jwt.claims',jsonb_build_object('sub',member,'session_id',sid,'role','authenticated')::text,true) from test_ids;
set local role authenticated;
select pg_temp.assert(public.is_couple_member(),'registered partner can read');
select pg_temp.assert(not public.is_admin(),'PIN is never admin');
reset role;
update private.partner_sessions set expires_at=now()-interval '1 second';
set local role authenticated;
select pg_temp.assert(not public.is_couple_member(),'server session expiry');
reset role;
update private.partner_sessions set expires_at=now()+interval '1 day';
select public.partner_pin_revoke();
set local role authenticated;
select pg_temp.assert(not public.is_couple_member(),'revoke invalidates existing JWT immediately');
reset role;
select pg_temp.assert(public.partner_pin_check('4826',repeat('f',64)) is null,'disabled partner cannot log in');
select 'ALL SECURITY ASSERTIONS PASSED' as result;
